begin;
select set_config('cbr.a',gen_random_uuid()::text,true),set_config('cbr.b',gen_random_uuid()::text,true),set_config('cbr.c',gen_random_uuid()::text,true),set_config('cbr.supplier',gen_random_uuid()::text,true),set_config('cbr.supplier2',gen_random_uuid()::text,true);
insert into auth.users(id,email) values(current_setting('cbr.a')::uuid,'cbr-a@example.invalid'),(current_setting('cbr.b')::uuid,'cbr-b@example.invalid'),(current_setting('cbr.c')::uuid,'cbr-c@example.invalid');
select set_config('request.jwt.claims',json_build_object('sub',current_setting('cbr.a'),'role','authenticated')::text,true);set local role authenticated;
insert into public.suppliers(id,name,phone) values(current_setting('cbr.supplier')::uuid,'Literal%_supplier','00123'),(current_setting('cbr.supplier2')::uuid,'Second',null);
insert into public.suppliers(name) values('Zero debt');
select public.post_cash_entry(gen_random_uuid(),'deposit',10000,'Report float');
select public.post_supplier_entry(gen_random_uuid(),current_setting('cbr.supplier')::uuid,'charge',1000,'Charge');
select public.post_supplier_entry(gen_random_uuid(),current_setting('cbr.supplier')::uuid,'payment',200,'Payment');
select public.post_supplier_entry(gen_random_uuid(),current_setting('cbr.supplier2')::uuid,'charge',300,'Charge');
insert into public.products(name,sale_price) values('Supplier report product',3000);
select set_config('cbr.purchase',gen_random_uuid()::text,true);
select public.post_supplier_purchase(current_setting('cbr.purchase')::uuid,jsonb_build_array(jsonb_build_object('product_id',(select id from public.products limit 1),'quantity_units',1000,'unit_cost',2000)),current_setting('cbr.supplier')::uuid,500,'Report invoice','');
select public.post_supplier_purchase_payment(gen_random_uuid(),current_setting('cbr.purchase')::uuid,300,'Invoice payment');
select public.post_purchase_return(gen_random_uuid(),current_setting('cbr.purchase')::uuid,'Supplier return',jsonb_build_array(jsonb_build_object('line_no',1,'quantity_units',250)));
do $$declare v jsonb;n bigint;begin
 select count(*) into n from public.supplier_entries;
 v:=public.get_supplier_balances_report();if v->>'count'<>'2' or v->>'debtors'<>'2' or v->>'balance'<>'1800' or v#>>'{rows,0,id}'<>current_setting('cbr.supplier') or v#>>'{rows,0,balance}'<>'1500' or v#>>'{rows,0,phone}'<>'00123' then raise exception 'report balances/order wrong';end if;
 if v->>'party_kind'<>'supplier' then raise exception 'supplier scope missing';end if;
 if jsonb_typeof(v#>'{rows,0,balance}')<>'string' or (v#>'{rows,0}')?'amount' then raise exception 'exact output contract wrong';end if;
 v:=public.get_supplier_balances_report('',false);if v->>'count'<>'3' or v->>'debtors'<>'2' or v->>'balance'<>'1800' then raise exception 'zero balance filter wrong';end if;
 v:=public.get_supplier_balances_report('%_',true);if v->>'count'<>'1' or v->>'balance'<>'1500' then raise exception 'literal search wrong';end if;
 v:=public.get_supplier_balances_report('0012',true);if v->>'count'<>'1' then raise exception 'phone filter wrong';end if;
 if (select count(*) from public.supplier_entries)<>n then raise exception 'report mutated ledger';end if;
 begin perform public.get_supplier_balances_report(repeat('x',101));raise exception 'oversized query allowed';exception when raise_exception then if sqlerrm<>'supplier_report_invalid_filters' then raise;end if;end;
end $$;
reset role;select set_config('request.jwt.claims',json_build_object('sub',current_setting('cbr.b'),'role','authenticated')::text,true);set local role authenticated;
do $$declare v jsonb;begin v:=public.get_supplier_balances_report('',false);if v->>'count'<>'0' or v->>'balance'<>'0' then raise exception 'other owner leak';end if;end $$;
insert into public.suppliers(name) select 'Cap '||g from generate_series(1,5001) g;
do $$declare v jsonb;begin begin perform public.get_supplier_balances_report('',false);raise exception 'truncated report allowed';exception when raise_exception then if sqlerrm<>'supplier_report_too_many_rows' then raise;end if;end;v:=public.get_supplier_balances_report('Cap 5001',false);if v->>'count'<>'1' then raise exception 'cap recovery filter wrong';end if;end $$;
reset role;
-- Rollback-only administrative fixture verifies sums beyond JavaScript Number precision.
insert into public.suppliers(id,owner_id,name) select gen_random_uuid(),current_setting('cbr.c')::uuid,'Large '||g from generate_series(1,92) g;
insert into public.supplier_balances(supplier_id,owner_id,balance) select id,owner_id,100000000000000 from public.suppliers where owner_id=current_setting('cbr.c')::uuid;
select set_config('request.jwt.claims',json_build_object('sub',current_setting('cbr.c'),'role','authenticated')::text,true);set local role authenticated;
do $$declare v jsonb;begin v:=public.get_supplier_balances_report();if v->>'balance'<>'9200000000000000' or v->>'debtors'<>'92' then raise exception 'large exact sum wrong';end if;end $$;
reset role;select set_config('request.jwt.claims','{}',true);set local role authenticated;
do $$begin begin perform public.get_supplier_balances_report();raise exception 'no UID allowed';exception when raise_exception then if sqlerrm<>'supplier_report_auth_required' then raise;end if;end;end $$;
reset role;set local role anon;
do $$begin begin perform public.get_supplier_balances_report();raise exception 'anon report allowed';exception when insufficient_privilege then null;end;end $$;
reset role;
select 'PASS: supplier balance snapshot, exact large sums, filters/sort, zero balances, full-list cap, no mutation, owner isolation and anon denial' verification;
rollback;
